/**
 * Machine-readable failure output for non-interactive callers.
 *
 * An agent driving the CLI had exactly one signal to work with: a non-zero
 * exit and a line of red prose on stderr. Telling "you have no wallet" apart
 * from "this endpoint wants a KYC attestation" — one is fatal, the other is a
 * two-command fix — meant matching English. So agents matched English.
 *
 * In JSON mode a failure is one object on STDERR:
 *
 *   {"error":{"code":"self_attestation_required","message":"…","details":{…}}}
 *
 * STDERR, specifically, and never stdout. `buy fetch` streams the response
 * BODY to stdout — that is the product, and it is frequently JSON itself.
 * Writing diagnostics there would interleave them with the payload and corrupt
 * whatever the caller was piping into. The split is: stdout is the answer,
 * stderr is what happened.
 *
 * AUTO-ENABLED ON A NON-TTY, because that is the shape of the problem: a human
 * gets a TTY and coloured prose, a pipe or an MCP subprocess gets JSON with no
 * flag to remember. `--json` forces it on; `--no-json` forces it off (for
 * `buy fetch … | less`, where a human is still reading).
 */
import { type BuyErrorCode } from '@celo/buy-core';
/** The failure envelope written to stderr in JSON mode. */
export type JsonErrorEnvelope = {
    error: {
        /**
         * A stable BuyErrorCode when the failure carried one, else 'unknown'.
         *
         * 'unknown' is deliberately in-band rather than omitted: a consumer can
         * always read `.error.code`, and an unrecognised value means "not
         * actionable by code" rather than "malformed output".
         */
        code: BuyErrorCode | 'unknown';
        message: string;
        details?: Record<string, unknown>;
    };
};
/**
 * Whether output should be machine-readable.
 *
 * Precedence: an explicit flag always wins; otherwise a non-TTY stdout implies
 * a program is reading. `isTTY` is `undefined` (not `false`) on a pipe, hence
 * the `!==  true` rather than a falsy check.
 */
export declare function shouldUseJson(flag: boolean | undefined, isTTY?: boolean): boolean;
/**
 * Build the envelope for an arbitrary thrown value.
 *
 * Accepts `unknown` because that is what a `catch` gives you, and a CLI's top
 * level must survive a non-Error being thrown.
 *
 * TOTAL BY CONSTRUCTION. This is the last thing all three exit paths do —
 * `main.ts`'s parse funnel, its `exitOverride`, and `exitWith`'s 27 call sites
 * — so a throw in here has nothing left to catch it: the process dies with no
 * output at all, on the exact code path whose job is to explain a failure.
 * Every read below is therefore guarded, and the promised object is emitted
 * even when the thing being described is hostile.
 */
export declare function toJsonError(err: unknown, extraDetails?: Record<string, unknown>): JsonErrorEnvelope;
export declare function formatJsonError(err: unknown, extraDetails?: Record<string, unknown>): string;
/**
 * One `-v` diagnostic line, as its own object: `{"log":"…"}`.
 *
 * Verbose output used to exist in JSON mode ONLY inside the failure envelope
 * (`details.log`), so a paid `buy curl … | tee` — the documented way to run
 * one, and a pipe, so JSON mode is on — printed nothing at all about the
 * quote, the signing or the settlement tx (#133). The same stream that carries
 * `{"warning":…}` and the envelope carries these now, one object per line, and
 * the envelope (when there is one) stays the LAST line so a consumer that
 * reads it from the tail is unaffected.
 *
 * Clipped with the same bound as an envelope field: the probe line echoes the
 * caller's whole argv, and a 100 KB `-d` body on it is not a diagnostic.
 */
export declare function formatJsonLog(message: string): string;
